   <valueClassDefinitions>
      <valueClassDefinition>
         <name>dateTimeClass</name>
         <description>Date-times should conform to ISO8601 date-time format YYYY-MM-DDThh:mm:ss.000000Z (year, month, day, hour (24h), minute, second, optional fractional seconds, and optional UTC time indicator. Any variation on the full form is allowed.</description>
         <attribute>
            <name>allowedCharacter</name>
            <value>digits</value>
            <value>T</value>
            <value>hyphen</value>
            <value>colon</value>
         </attribute>
         <attribute>
            <name>hedId</name>
            <value>HED_0011301</value>
         </attribute>
      </valueClassDefinition>
      <valueClassDefinition>
         <name>nameClass</name>
         <description>Value class designating values that have the characteristics of node names. The allowed characters are alphanumeric, hyphen, and underscore.</description>
         <attribute>
            <name>allowedCharacter</name>
            <value>letters</value>
            <value>digits</value>
            <value>underscore</value>
            <value>hyphen</value>
         </attribute>
         <attribute>
            <name>hedId</name>
            <value>HED_0011302</value>
         </attribute>
      </valueClassDefinition>
      <valueClassDefinition>
         <name>numericClass</name>
         <description>Value must be a valid numerical value.</description>
         <attribute>
            <name>allowedCharacter</name>
            <value>digits</value>
            <value>E</value>
            <value>e</value>
            <value>plus</value>
            <value>hyphen</value>
            <value>period</value>
         </attribute>
         <attribute>
            <name>hedId</name>
            <value>HED_0011303</value>
         </attribute>
      </valueClassDefinition>
      <valueClassDefinition>
         <name>posixPath</name>
         <description>Posix path specification.</description>
         <attribute>
            <name>allowedCharacter</name>
            <value>digits</value>
            <value>letters</value>
            <value>slash</value>
            <value>colon</value>
         </attribute>
         <attribute>
            <name>hedId</name>
            <value>HED_0011304</value>
         </attribute>
      </valueClassDefinition>
      <valueClassDefinition>
         <name>textClass</name>
         <description>Values that have the characteristics of text such as in descriptions. The text characters include printable characters (32 &lt;= ASCII&lt; 127) excluding comma, square bracket and curly braces as well as non ASCII (ASCII codes &gt; 127).</description>
         <attribute>
            <name>allowedCharacter</name>
            <value>text</value>
         </attribute>
         <attribute>
            <name>hedId</name>
            <value>HED_0011305</value>
         </attribute>
      </valueClassDefinition>
   </valueClassDefinitions>
